// XS glue of face-finder.js. The work is in face-finder-core.c; the cascade is generated by build-host.mjs from
// facefinder.bin (aligned, in flash).
#include "xsmc.h"
#include "xsHost.h"
#include "face-finder-core.h"
#include "sound-side-core.h"
#include <stdlib.h>
#include <stdio.h>
#include "esp_wifi.h"
#include "esp_heap_caps.h"
#include "esp_event.h"

extern const unsigned char robottino_facefinder[];
static uint8_t *gGrey;
static int32_t gTested;

void xs_robottino_face_find(xsMachine *the) {
	void *data;
	xsUnsignedValue length;
	int width = xsmcToInteger(xsArg(1)), height = xsmcToInteger(xsArg(2));
	RobottinoFace hint, out;
	xsmcGetBufferReadable(xsArg(0), &data, &length);
	if (width < 24 || height < 24 || width > 255 || height > 255 || width * height > ROBOTTINO_FACE_MAX_PIXELS || length < (xsUnsignedValue)(width * height * 2))
		xsRangeError("bad picture");
	if (!gGrey) {
		gGrey = malloc(ROBOTTINO_FACE_MAX_PIXELS);
		if (!gGrey) xsUnknownError("no memory");
	}
	hint.x = (int16_t)xsmcToInteger(xsArg(3)); hint.y = (int16_t)xsmcToInteger(xsArg(4)); hint.size = (int16_t)xsmcToInteger(xsArg(5));
	robottino_face_grey((const uint8_t *)data, gGrey, width * height);
	int found = robottino_face_find(robottino_facefinder, gGrey, width, height, hint.size > 0 ? &hint : NULL,
	                                xsmcToInteger(xsArg(6)), xsmcToInteger(xsArg(7)), &out);
	gTested = out.tested;
	if (!found) { xsmcSetInteger(xsResult, 0); return; }
	double score = out.score * 10.0 + 0.5;
	if (score < 1) score = 1;
	if (score > 65535) score = 65535;
	xsmcSetNumber(xsResult, (double)out.x + 256.0 * out.y + 65536.0 * out.size + 16777216.0 * (double)(uint32_t)score);
}

void xs_robottino_face_tested(xsMachine *the) {
	xsmcSetInteger(xsResult, gTested);
}

// The neural detector (face-dl.cpp), when the host was built with it: it gives its two functions here at start-up.
static int (*gNeuralStart)(const uint8_t *, int, int, int, int, int);
static int (*gNeuralPoll)(int16_t *);
static int (*gNeuralInfo)(char *, int);
static int (*gNeuralSize)(int, int);
static int gNeuralMs;

void robottino_face_backend(int (*start)(const uint8_t *, int, int, int, int, int), int (*poll)(int16_t *), int (*info)(char *, int), int (*size)(int, int)) {
	gNeuralStart = start;
	gNeuralPoll = poll;
	gNeuralInfo = info;
	gNeuralSize = size;
}

void xs_robottino_face_neural_size(xsMachine *the) {
	xsmcSetBoolean(xsResult, gNeuralSize != NULL && gNeuralSize(xsmcToInteger(xsArg(0)), xsmcToInteger(xsArg(1))) == 1);
}

void xs_robottino_face_neural(xsMachine *the) {
	xsmcSetBoolean(xsResult, gNeuralStart != NULL && gNeuralPoll != NULL);
}

// 1: started on a copy of the picture; 0: the last search is still running; -1: it cannot run.
void xs_robottino_face_neural_start(xsMachine *the) {
	void *data;
	xsUnsignedValue length;
	int width = xsmcToInteger(xsArg(1)), height = xsmcToInteger(xsArg(2));
	xsmcGetBufferReadable(xsArg(0), &data, &length);
	if (!gNeuralStart || width < 24 || height < 24 || width > 255 || height > 255 || width * height > ROBOTTINO_FACE_MAX_PIXELS || length < (xsUnsignedValue)(width * height * 2)) {
		xsmcSetInteger(xsResult, -1);
		return;
	}
	// Argument 3: how to search (0 or left out: both networks; 1: quick, first network only, near x, y of arguments 4
	// and 5; 2: the other, slower detector).
	int quick = xsmcArgc > 3 ? xsmcToInteger(xsArg(3)) : 0, x = xsmcArgc > 4 ? xsmcToInteger(xsArg(4)) : 0, y = xsmcArgc > 5 ? xsmcToInteger(xsArg(5)) : 0;
	xsmcSetInteger(xsResult, gNeuralStart((const uint8_t *)data, width, height, quick == 2 ? 2 : quick ? 1 : 0, x, y));
}

// -1: still searching, or nothing asked; 0: no face; otherwise x + y*256 + size*65536 + (score 0…1000)*16777216.
void xs_robottino_face_neural_poll(xsMachine *the) {
	int16_t answer[6];
	if (!gNeuralPoll || gNeuralPoll(answer) != 1) {
		xsmcSetInteger(xsResult, -1);
		return;
	}
	gNeuralMs = answer[5];
	if (!answer[0]) {
		xsmcSetInteger(xsResult, 0);
		return;
	}
	int x = answer[1] < 0 ? 0 : answer[1] > 255 ? 255 : answer[1], y = answer[2] < 0 ? 0 : answer[2] > 255 ? 255 : answer[2];
	int size = answer[3] < 1 ? 1 : answer[3] > 255 ? 255 : answer[3], score = answer[4] < 1 ? 1 : answer[4];
	xsmcSetNumber(xsResult, (double)x + 256.0 * y + 65536.0 * size + 16777216.0 * (double)score);
}

void xs_robottino_face_neural_ms(xsMachine *the) {
	xsmcSetInteger(xsResult, gNeuralMs);
}

void xs_robottino_face_neural_info(xsMachine *the) {
	char text[128];
	text[0] = 0;
	if (gNeuralInfo) gNeuralInfo(text, sizeof(text));
	xsmcSetString(xsResult, text);
}

// TEMPORARY diagnostics (14 Nov 2026): the robot's Wi-Fi was dropping and coming back, 38 times in forty minutes, and
// the host says only that it happened. This gives what the chip itself knows: how strong it hears the access point
// now and on which channel, how many times the link has dropped since the first call, and the reason the chip gave for
// the last drop (esp_wifi_types: 200 the access point was no longer heard, 2 and 3 it sent us away, 8 we left, 15 the
// key exchange timed out, 201 it was not found) with the strength at that moment.
static int gWifiHooked, gWifiDrops, gWifiReason, gWifiDropRssi;

static void robottino_wifi_event(void *arg, esp_event_base_t base, int32_t id, void *data) {
	wifi_event_sta_disconnected_t *event = (wifi_event_sta_disconnected_t *)data;
	gWifiDrops++;
	gWifiReason = event ? event->reason : -1;
	gWifiDropRssi = event ? event->rssi : 0;
}

void xs_robottino_wifi_info(xsMachine *the) {
	char text[96];
	wifi_ap_record_t ap;
	int rssi = 0, channel = 0;
	if (!gWifiHooked) {
		gWifiHooked = 1;
		esp_event_handler_instance_register(WIFI_EVENT, WIFI_EVENT_STA_DISCONNECTED, robottino_wifi_event, NULL, NULL);
	}
	if (ESP_OK == esp_wifi_sta_get_ap_info(&ap)) {
		rssi = ap.rssi;
		channel = ap.primary;
	}
	snprintf(text, sizeof(text), "rssi %d ch %d drops %d last %d at %d", rssi, channel, gWifiDrops, gWifiReason, gWifiDropRssi);
	xsmcSetString(xsResult, text);
}

// Which side a sound comes from (sound-side-core.c). The argument is what embedded:io/audio/in gives with two
// channels: 16-bit samples, the two microphones in turn. One number comes back, 0 when there is too little to say:
//   level + 65536 * quality + 16777216 * (lag16 + 128)
void xs_robottino_sound_side(xsMachine *the) {
	void *data;
	xsUnsignedValue length;
	RobottinoSoundSide side;
	xsmcGetBufferReadable(xsArg(0), &data, &length);
	if (((uintptr_t)data & 1) || !robottino_sound_side((const int16_t *)data, (int)(length / 4), &side)) {
		xsmcSetInteger(xsResult, 0);
		return;
	}
	if (side.level > 65535) side.level = 65535;
	xsmcSetNumber(xsResult, (double)side.level + 65536.0 * side.quality + 16777216.0 * (double)(side.lag16 + 128));
}

// How much memory the robot has and how much of it is free (14 Nov 2026, owner: «verifica se è possibile aumentare
// la RAM»). Two memories: the one inside the chip (fast, small: everything that must be quick or is used by
// interrupts lives there) and the external one on the same module (8 MB, slower). For each: its size, what is free
// now, the least that has ever been free since the start, and the largest piece that can be had in one go. In KB.
void xs_robottino_memory_info(xsMachine *the) {
	char text[160];
	snprintf(text, sizeof(text), "inside %d free %d low %d piece %d | outside %d free %d low %d piece %d KB",
		(int)(heap_caps_get_total_size(MALLOC_CAP_INTERNAL) / 1024), (int)(heap_caps_get_free_size(MALLOC_CAP_INTERNAL) / 1024),
		(int)(heap_caps_get_minimum_free_size(MALLOC_CAP_INTERNAL) / 1024), (int)(heap_caps_get_largest_free_block(MALLOC_CAP_INTERNAL) / 1024),
		(int)(heap_caps_get_total_size(MALLOC_CAP_SPIRAM) / 1024), (int)(heap_caps_get_free_size(MALLOC_CAP_SPIRAM) / 1024),
		(int)(heap_caps_get_minimum_free_size(MALLOC_CAP_SPIRAM) / 1024), (int)(heap_caps_get_largest_free_block(MALLOC_CAP_SPIRAM) / 1024));
	xsmcSetString(xsResult, text);
}

// The camera picture as a JPEG for the Live video (video-jpeg.c, compiled with the IDF project: it hands its
// functions over when the host starts). videoJpeg(frame, width, height, quality, head): frame is the camera's RGB565
// little-endian buffer; what comes back is a new ArrayBuffer of `head` empty bytes (for the caller's own header)
// followed by the JPEG, or a negative number when it could not be made (-1 bad arguments, -2 no memory, -3 the
// encoder refused, -4 larger than VIDEO_JPEG_MAX, -5 this host has no encoder). The JPEG is made in a buffer of the
// external memory kept from one picture to the next; videoEnd() gives encoder and buffer back.
#define VIDEO_JPEG_MAX 24000
static int (*gVideoEncode)(const uint8_t *, int, int, int, uint8_t *, int);
static void (*gVideoEnd)(void);
static int (*gVideoMs)(void);
static uint8_t *gVideoOut;

void robottino_video_backend(int (*encode)(const uint8_t *, int, int, int, uint8_t *, int), void (*end)(void), int (*ms)(void)) {
	gVideoEncode = encode;
	gVideoEnd = end;
	gVideoMs = ms;
}

void xs_robottino_video_jpeg(xsMachine *the) {
	void *data;
	xsUnsignedValue length;
	int width = xsmcToInteger(xsArg(1)), height = xsmcToInteger(xsArg(2)), quality = xsmcToInteger(xsArg(3)), head = xsmcToInteger(xsArg(4)), size;
	if (!gVideoEncode) {
		xsmcSetInteger(xsResult, -5);
		return;
	}
	xsmcGetBufferReadable(xsArg(0), &data, &length);
	if (width < 1 || height < 1 || width > 320 || height > 240 || head < 0 || head > 64 || length < (xsUnsignedValue)(width * height * 2)) {
		xsmcSetInteger(xsResult, -1);
		return;
	}
	if (!gVideoOut) gVideoOut = (uint8_t *)heap_caps_malloc(VIDEO_JPEG_MAX, MALLOC_CAP_SPIRAM);
	if (!gVideoOut) {
		xsmcSetInteger(xsResult, -2);
		return;
	}
	size = gVideoEncode((const uint8_t *)data, width, height, quality, gVideoOut, VIDEO_JPEG_MAX);
	if (size <= 0) {
		xsmcSetInteger(xsResult, size ? size : -3);
		return;
	}
	xsmcSetArrayBuffer(xsResult, NULL, head + size);
	c_memcpy((uint8_t *)xsmcToArrayBuffer(xsResult) + head, gVideoOut, size);
}

void xs_robottino_video_end(xsMachine *the) {
	if (gVideoEnd) gVideoEnd();
	if (gVideoOut) {
		heap_caps_free(gVideoOut);
		gVideoOut = NULL;
	}
}

// How long the last JPEG took to make, in ms.
void xs_robottino_video_ms(xsMachine *the) {
	xsmcSetInteger(xsResult, gVideoMs ? gVideoMs() : 0);
}

// The start-up video (video-jpeg.c screenDecode, 14 Nov 2026). screenJpeg(data, offset, length, bigEndian): one JPEG
// picture taken from data (an ArrayBuffer or a resource of the MOD) at offset, made into screen pixels. What comes
// back is a host buffer over the pixels (width*height*2 bytes, in the display's order when bigEndian), always the
// same memory: it is written again by the next call, so a picture is drawn before the next one is asked for. Or a
// negative number (see video-jpeg.c; -5: this host cannot do it). screenEnd() gives the memory back.
static int (*gScreenDecode)(const uint8_t *, int, int, uint8_t **, int *, int *);
static void (*gScreenEnd)(void);
static int gScreenWidth, gScreenHeight;
int robottino_screen_ms(void);

void robottino_screen_backend(int (*decode)(const uint8_t *, int, int, uint8_t **, int *, int *), void (*end)(void)) {
	gScreenDecode = decode;
	gScreenEnd = end;
}

void xs_robottino_screen_jpeg(xsMachine *the) {
	void *data;
	xsUnsignedValue length;
	int offset = xsmcToInteger(xsArg(1)), count = xsmcToInteger(xsArg(2)), bigEndian = xsmcTest(xsArg(3)), size, width = 0, height = 0;
	uint8_t *pixels = NULL;
	if (!gScreenDecode) {
		xsmcSetInteger(xsResult, -5);
		return;
	}
	xsmcGetBufferReadable(xsArg(0), &data, &length);
	if (offset < 0 || count < 4 || (xsUnsignedValue)offset + (xsUnsignedValue)count > length) {
		xsmcSetInteger(xsResult, -1);
		return;
	}
	size = gScreenDecode((const uint8_t *)data + offset, count, bigEndian, &pixels, &width, &height);
	if (size <= 0 || !pixels) {
		xsmcSetInteger(xsResult, size ? size : -3);
		return;
	}
	gScreenWidth = width;
	gScreenHeight = height;
	xsResult = xsNewHostObject(NULL); // a host buffer must be set on a host object (as bmi270.c and flash.c do)
	xsmcSetHostBuffer(xsResult, pixels, size);
}

/**
 * Width and height of the last picture made by screenJpeg, how long it took, and whether the memory of the whole
 * robot is still in order (1) or damaged (0): «width height ms intact». Walks all the memory: once, at the end of the
 * video, not for every picture (14 Nov 2026: the first try restarted the robot a few seconds after the first picture,
 * with the memory found damaged by the face detector).
 */
void xs_robottino_screen_info(xsMachine *the) {
	char text[40];
	snprintf(text, sizeof(text), "%d %d %d %d", gScreenWidth, gScreenHeight, gScreenDecode ? robottino_screen_ms() : 0, heap_caps_check_integrity_all(true) ? 1 : 0);
	xsmcSetString(xsResult, text);
}

void xs_robottino_screen_end(xsMachine *the) {
	if (gScreenEnd) gScreenEnd();
}

